files.content:
:root {
  --bg: #1e1b2e;
  --card: #2a2540;
  --text: #f0edf7;
  --muted: #a89fc4;
  --accent: #8b7cf6;
  --accent-hover: #a395ff;
  --accent-pressed: #6f5fd6;
  --danger: #e06c75;
  --danger-hover: #f08088;
  --success: #7ec699;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 1.5rem;
}

.app {
  width: 100%;
  max-width: 560px;
  background: var(--card);
  border-radius: var(--radius);
  padding: 2rem 1.5rem;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.35);
}

.app-header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  font-size: 1.6rem;
  margin: 0 0 0.25rem;
  letter-spacing: 0.02em;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 0.95rem;
}

.stats {
  text-align: center;
  margin-bottom: 1rem;
}

.stat {
  margin: 0;
  font-size: 1.05rem;
  color: var(--muted);
}

.stat strong {
  color: var(--text);
}

.controls {
  display: flex;
  justify-content: center;
  margin-bottom: 1.5rem;
}

button {
  font-family: inherit;
  font-size: 1rem;
  border: none;
  border-radius: 8px;
  padding: 0.6rem 1.2rem;
  cursor: pointer;
  background: var(--accent);
  color: #fff;
  transition: background 0.15s ease, transform 0.05s ease;
}

button:hover {
  background: var(--accent-hover);
}

button:active {
  background: var(--accent-pressed);
  transform: scale(0.98);
}

button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

button[aria-pressed="true"] {
  background: var(--accent-pressed);
  box-shadow: inset 0 0 0 2px var(--text);
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.book {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  background: var(--bg);
  border-radius: 8px;
  padding: 0.75rem 1rem;
  flex-wrap: wrap;
}

.book-info {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  min-width: 0;
  flex: 1 1 12rem;
}

.book-title {
  font-weight: 600;
  font-size: 1rem;
  word-break: break-word;
}

.book-author {
  font-size: 0.9rem;
  color: var(--muted);
}

.book-status {
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.book-status.available {
  color: var(--success);
}

.book-status.checked-out {
  color: var(--danger);
}

.book-action {
  flex-shrink: 0;
  background: var(--accent);
  color: #fff;
  padding: 0.5rem 0.9rem;
  font-size: 0.9rem;
}

.book-action.return {
  background: var(--danger);
}

.book-action.return:hover {
  background: var(--danger-hover);
}

.book-action:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.empty {
  text-align: center;
  color: var(--muted);
  margin: 1rem 0 0;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  body {
    padding: 1rem;
  }
  .app {
    padding: 1.5rem 1rem;
  }
  .book {
    padding: 0.75rem;
  }
  .book-action {
    width: 100%;
    text-align: center;
  }
}

(function () {
  'use strict';

  const books = [
    { id: 1, title: 'The Pixel Frontier', author: 'Ada Lovelace', checkedOut: false },
    { id: 2, title: 'Bits & Bytes', author: 'Alan Turing', checkedOut: true },
    { id: 3, title: 'Canvas Chronicles', author: 'Grace Hopper', checkedOut: false },
    { id: 4, title: 'CSS: The Good Parts', author: 'Hedy Lamarr', checkedOut: false },
    { id: 5, title: 'JavaScript Journeys', author: 'Tim Berners-Lee', checkedOut: true },
    { id: 6, title: 'Responsive Realms', author: 'Margaret Hamilton', checkedOut: false }
  ];

  const listEl = document.getElementById('book-list');
  const checkedCountEl = document.getElementById('checked-count');
  const totalCountEl = document.getElementById('total-count');
  const filterBtn = document.getElementById('filter-btn');
  const emptyMsg = document.getElementById('empty-message');

  let showAvailableOnly = false;

  function render() {
    const visibleBooks = showAvailableOnly
      ? books.filter((b) => !b.checkedOut)
      : books;

    listEl.innerHTML = '';

    visibleBooks.forEach((book) => {
      const li = document.createElement('li');
      li.className = 'book';

      const info = document.createElement('div');
      info.className = 'book-info';

      const title = document.createElement('span');
      title.className = 'book-title';
      title.textContent = book.title;

      const author = document.createElement('span');
      author.className = 'book-author';
      author.textContent = book.author;

      const status = document.createElement('span');
      status.className = 'book-status ' + (book.checkedOut ? 'checked-out' : 'available');
      status.textContent = book.checkedOut ? 'Checked out' : 'Available';

      info.appendChild(title);
      info.appendChild(author);

      const action = document.createElement('button');
      action.type = 'button';
      action.className = 'book-action' + (book.checkedOut ? ' return' : '');
      action.textContent = book.checkedOut ? 'Return' : 'Check out';
      action.setAttribute('aria-label', (book.checkedOut ? 'Return ' : 'Check out ') + book.title);
      action.addEventListener('click', () => {
        book.checkedOut = !book.checkedOut;
        render();
      });

      li.appendChild(info);
      li.appendChild(status);
      li.appendChild(action);
      listEl.appendChild(li);
    });

    const checkedOutCount = books.filter((b) => b.checkedOut).length;
    checkedCountEl.textContent = String(checkedOutCount);
    totalCountEl.textContent = String(books.length);

    emptyMsg.hidden = visibleBooks.length !== 0;
  }

  filterBtn.addEventListener('click', () => {
    showAvailableOnly = !showAvailableOnly;
    filterBtn.setAttribute('aria-pressed', String(showAvailableOnly));
    filterBtn.textContent = showAvailableOnly ? 'Show all books' : 'Show available only';
    render();
  });

  render();
})();
